// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 seqNum_,
        bytes32 batcherHash_,
        uint256 l1FeeOverhead_,
        uint256 l1FeeScalar_
    ) public {
        // Only the depositor account (default address(0)) may set L1 block values.
        vm.prank(c.depositorAccount());
        c.setL1BlockValues(
            number_,
            timestamp_,
            basefee_,
            hash_,
            seqNum_,
            batcherHash_,
            l1FeeOverhead_,
            l1FeeScalar_
        );

        // Rule: a successful setL1BlockValues call must not change stored L1 fee overhead; it stays 0.
        assertTrue(c.l1FeeOverhead() == 0);
    }
}
